// 問題以 base64 傳給 SSH 指令：base64 只有 A-Za-z0-9+/=，不含任何 shell 特殊字元，
// 問題文字裡的引號、$()、反引號、換行都不會被 shell 解讀。
const raw = $input.item.json['你的問題'];
const question_b64 = Buffer.from(String(raw === undefined || raw === null ? '' : raw), 'utf8').toString('base64');
return { question_b64 };

const output = $input.item.json.stdout;
const match = output.match(/【回答】\s*([\s\S]*?)\n\n【耗時】/);
const answer = match ? match[1].trim() : output;

// 判斷這題實際上有沒有跑思考模式：可能是整批預設就開啟(DEFAULT_THINKING)，
// 也可能是 detect_think_reason() 逐題規則覆寫開啟，兩種來源都要認。
const think_used = /思考模式\s*開啟/.test(output) ||
  /本題自動切換為 --think/.test(output);

const timeMatch = output.match(/端到端\s*([\d.]+)s/);
const total_time_s = timeMatch ? parseFloat(timeMatch[1]) : null;

const tokenMatch = output.match(/輸出\s*(\d+)\s*tokens/);
const completion_tokens = tokenMatch ? parseInt(tokenMatch[1], 10) : null;

const inputMatch = output.match(/輸入\s*(\d+)\s*tokens/);
const prompt_tokens = inputMatch ? parseInt(inputMatch[1], 10) : null;

const question = $('On form submission').first().json['你的問題'];

const headingsMatch = output.match(/【檢索到的片段】\s*([\s\S]*?)\n\n/);
const retrieved_headings = headingsMatch ? headingsMatch[1].trim() : '';

const contextMatch = output.match(/【送進模型的完整片段內容】\s*([\s\S]*?)\n\n【回答】/);
const retrieved_context_full = contextMatch ? contextMatch[1].trim() : '';

const hex = (len) => Array.from({ length: len }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const nowMs = Date.now();
const startMs = total_time_s ? nowMs - Math.round(total_time_s * 1000) : nowMs;

// Langfuse 只收執行資料（耗時、token 數、成功、模型名稱、腳本名稱）：不送問題、回答、檢索片段。
// 問題與回答只留在這個節點的輸出（n8n 本機執行紀錄），暫緩複核時從那裡看。
const langfuse_body = {
  resourceSpans: [
    {
      resource: {
        attributes: [
          { key: "service.name", value: { stringValue: "psf-eim-rag-n8n" } }
        ]
      },
      scopeSpans: [
        {
          scope: { name: "n8n-psf-eim-rag" },
          spans: [
            {
              traceId: hex(32),
              spanId: hex(16),
              name: "psf_eim_rag_answer",
              kind: 1,
              startTimeUnixNano: `${startMs}000000`,
              endTimeUnixNano: `${nowMs}000000`,
              attributes: [
                { key: "langfuse.trace.name", value: { stringValue: "psf-eim-rag-qa" } },
                { key: "langfuse.observation.type", value: { stringValue: "generation" } },
                { key: "langfuse.observation.model.name", value: { stringValue: "Qwen/Qwen3-30B-A3B" } },
                { key: "gen_ai.usage.input_tokens", value: { intValue: prompt_tokens || 0 } },
                { key: "gen_ai.usage.output_tokens", value: { intValue: completion_tokens || 0 } },
                { key: "langfuse.observation.metadata.think_used", value: { boolValue: think_used } },
                { key: "langfuse.observation.metadata.total_time_s", value: { doubleValue: total_time_s || 0 } },
                { key: "langfuse.observation.metadata.source", value: { stringValue: "n8n" } },
                { key: "langfuse.observation.metadata.script", value: { stringValue: "rag_answer.py" } }
              ],
              status: { code: 1 }
            }
          ]
        }
      ]
    }
  ]
};

const traceId = langfuse_body.resourceSpans[0].scopeSpans[0].spans[0].traceId;

return { answer, think_used, total_time_s, completion_tokens, prompt_tokens, question,
         retrieved_headings, retrieved_context_full, traceId, langfuse_body };

const src = $('Code in JavaScript').first().json;
const answer = src.answer || '';

// 資訊性欄位：是否明確以「文件中未提及」誠實回應（不再拿來當 needs_review 的硬性
// 判斷依據 —— 要求逐字出現「文件片段」字樣太嚴格，一般正常、有憑有據的直接回答
// 本來就不會這樣寫，之前這樣設計反而對「答得好的完整回答」產生大量假陽性）
const explicitly_declined = /文件中(並)?未提及/.test(answer);

// 截斷判斷改用真正可靠的訊號：生成是否真的撞到 max_tokens 上限（rag_answer.py
// 預設 max_tokens=2048，SSH 呼叫沒有覆寫這個值）。撞上限才代表生成中途被切斷；
// 純粹用「結尾標點」猜測太脆弱 —— 正常的條列式回答常以「）」「」」等收尾，
// 之前的版本會把這種正常結尾誤判為截斷。
const MAX_TOKENS = 2048;
const hit_token_cap = typeof src.completion_tokens === 'number' &&
  src.completion_tokens >= MAX_TOKENS - 8; // 留一點緩衝給極少數提前 stop 的邊界情況
const not_truncated = answer.trim().length > 0 && !hit_token_cap;

// 亂碼/生成迴圈偵測：Unicode 替代字元,或同一字元連續出現 10 次以上
const has_garbled = /�/.test(answer) || /(.)\1{9,}/.test(answer);
const no_garbled = !has_garbled;

// deterministic_pass 現在只擋「明顯故障」的情況（截斷、亂碼、空白），不再要求
// 特定措辭 —— 措辭層面的忠實度判斷交給看得到全文的 LLM judge 去做，比規則式
// 關鍵字比對可靠得多。
const deterministic_pass = not_truncated && no_garbled;

return {
  ...src,
  explicitly_declined,
  not_truncated,
  no_garbled,
  deterministic_pass,
};

