={{ {
  "model": "Qwen/Qwen3-30B-A3B",
  "messages": [
    { "role": "system", "content": "你是嚴格的 RAG 問答品質評審員。你會看到：使用者問題、檢索到的文件片段全文、以及系統產生的回答。請針對兩個維度各給 1-10 的整數評分：\n1. faithfulness(忠實度)：逐項核對回答裡的每個具體主張(名稱、數字、職責描述、專有名詞等)是否能在提供的文件片段全文裡找到依據。只要是片段全文裡明確寫到的內容，即使回答是逐字引用或改寫，都算忠實，不算捏造；只有片段全文找不到根據、且回答仍明確斷言的內容才算捏造，該大幅扣分。若片段全文不足以回答問題，回答有沒有誠實說「文件中未提及」而不是硬掰。\n2. relevance(相關性)：回答是否切題回應了使用者的問題，而不是答非所問或離題。\n請只輸出一個 JSON 物件，格式為 {\"faithfulness\": <整數>, \"relevance\": <整數>, \"reasoning\": \"<20字以內的簡短理由>\"}，不要有任何其他文字、不要用 markdown code fence。" },
    { "role": "user", "content": "問題：" + $json.question + "\n\n檢索到的文件片段全文：\n" + ($json.retrieved_context_full || $json.retrieved_headings) + "\n\n系統回答：\n" + $json.answer }
  ],
  "temperature": 0,
  "max_tokens": 300,
  "chat_template_kwargs": { "enable_thinking": false }
} }}

parameters.jsCode:
const src = $('QA Deterministic Checks').first().json;

let raw = '';
try {
  raw = $input.item.json.choices[0].message.content || '';
} catch (e) {
  raw = '';
}
raw = raw.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
raw = raw.replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let faithfulness = null, relevance = null, reasoning = '';
let judge_parse_error = false;
try {
  const parsed = JSON.parse(raw);
  faithfulness = Number(parsed.faithfulness);
  relevance = Number(parsed.relevance);
  reasoning = String(parsed.reasoning || '').slice(0, 200);
  if (!Number.isFinite(faithfulness) || !Number.isFinite(relevance)) {
    judge_parse_error = true;
  }
} catch (e) {
  judge_parse_error = true;
}

// Known Issue #7 對應的保守門檻：忠實度 < 7、格式/引用檢查沒過、或 judge 輸出解析失敗，
// 一律標記為需人工審核（sunset warning：/api/public/ingestion 2026-11-16 後只接受
// score-create，其餘事件類型會被拒絕；本節點只送 score-create，屬於長期支援路徑）。
const FAITHFULNESS_THRESHOLD = 7;
const needs_review = judge_parse_error || !src.deterministic_pass ||
  faithfulness === null || faithfulness < FAITHFULNESS_THRESHOLD;

const hex = (len) => Array.from({ length: len }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const uuid4 = () => `${hex(8)}-${hex(4)}-4${hex(3)}-a${hex(3)}-${hex(12)}`;
const nowIso = new Date().toISOString();
const traceId = src.traceId;

function scoreEvent(name, value, dataType, comment) {
  return {
    id: uuid4(),
    timestamp: nowIso,
    type: 'score-create',
    body: { id: uuid4(), traceId, name, value, dataType, comment: comment || null },
  };
}

// 只送分數（數字/布林）。評審理由（reasoning）會帶到回答內容，不送 Langfuse，只留在本機執行紀錄。
const qa_batch_body = {
  batch: [
    scoreEvent('faithfulness', faithfulness ?? 0, 'NUMERIC',
      judge_parse_error ? 'judge 輸出無法解析' : null),
    scoreEvent('relevance', relevance ?? 0, 'NUMERIC', null),
    scoreEvent('needs_review', needs_review ? 1 : 0, 'BOOLEAN',
      judge_parse_error ? 'judge 輸出解析失敗，保守標記需人工審核' :
      (!src.deterministic_pass ? '格式/引用檢查未通過' : null)),
  ],
};

return {
  ...src,
  faithfulness,
  relevance,
  judge_reasoning: reasoning,
  judge_parse_error,
  needs_review,
  qa_batch_body,
};

const src = $('Code in JavaScript').first().json;
const traceId = src.traceId;

const hex = (len) => Array.from({ length: len }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const nowMs = Date.now();

const tag_body = {
  resourceSpans: [
    {
      resource: { attributes: [{ key: "service.name", value: { stringValue: "psf-eim-rag-n8n" } }] },
      scopeSpans: [
        {
          scope: { name: "n8n-psf-eim-rag" },
          spans: [
            {
              traceId: traceId,
              spanId: hex(16),
              name: "qa_flag_pending_review",
              kind: 1,
              startTimeUnixNano: `${nowMs}000000`,
              endTimeUnixNano: `${nowMs}000000`,
              attributes: [
                {
                  key: "langfuse.trace.tags",
                  value: { arrayValue: { values: [{ stringValue: "pending-review" }] } }
                }
              ],
              status: { code: 0 }
            }
          ]
        }
      ]
    }
  ]
};

return { tag_body, traceId };
